(7258302, 1128989, 177030, '<td valign="top">I have no clue what this is, but like the effect.  The prominent foreground reminds me of car tail light from the 50''s.</td>', 'I have no clue what this is, but like the effect.  The prominent foreground reminds me of car tail light from the 50''s.', '2014-09-03 14:49:11.000000', NULL, 1),
(7258304, 1128403, 170281, '<td valign="top">This exemplifies the them of abstract macro.  The colors are great and there are so many things to view in the photo,  Very well done.</td>', 'This exemplifies the them of abstract macro.  The colors are great and there are so many things to view in the photo,  Very well done.', '2014-09-03 14:51:40.000000', NULL, 1),
(7258306, 1128602, 177030, '<td valign="top">My pick for winner. Simple and clean with a pleasing range of tones. What is not to like, other than being a bit cliché?  Hey, it works. Curious what you used for a background.</td>', 'My pick for winner. Simple and clean with a pleasing range of tones. What is not to like, other than being a bit cliché?  Hey, it works. Curious what you used for a background.', '2014-09-03 14:54:45.000000', NULL, 1),
(7258311, 1128514, 170281, '<td valign="top">Very nice work sticking with the theme.  Colors and patterns make for an interesting photo.  Nice work.</td>', 'Very nice work sticking with the theme.  Colors and patterns make for an interesting photo.  Nice work.', '2014-09-03 15:05:50.000000', NULL, 1),
(7258312, 1128706, 170281, '<td valign="top">This is what I hope to see in photos...someone who has found a unique perspective or view and captured it in a creative/artistic manner.  Very nicely done.</td>', 'This is what I hope to see in photos...someone who has found a unique perspective or view and captured it in a creative/artistic manner.  Very nicely done.', '2014-09-03 15:07:18.000000', NULL, 1),
